static void otto_pose(int a,int b,int c,int d){int values[]={a,b,c,d};for(int i=0;i<4;++i){int gpio=otto_pin(i);if(gpio>=0)servo(gpio,std::clamp(otto_center(i)+(otto_reversed(i)?-values[i]:values[i]),0,180));}}
