static void matrix_shift(uint8_t address,uint8_t data){uint16_t packet=((uint16_t)address<<8)|data;for(int bit=15;bit>=0;--bit){output(matrix.clk,0);output(matrix.din,(packet>>bit)&1);output(matrix.clk,1);}}
static uint8_t reverse_byte(uint8_t value){value=(value&0xf0)>>4|(value&0x0f)<<4;value=(value&0xcc)>>2|(value&0x33)<<2;return (value&0xaa)>>1|(value&0x55)<<1;}
